  it('409s when someone else saved in between, rather than clobbering them', async () => {
    const conflict = Object.assign(new Error('Someone else saved the library while you were editing.'), { status: 409 });
    vi.mocked(repo.saveLibrary).mockRejectedValue(conflict);

    const res = await request(appAs(true)).put('/library/virtues/v-might').send({ Name: 'Changed' });

    expect(res.status).toBe(409);
    expect(res.body.error).toMatch(/someone else saved/i);
  });

  describe('audit log failures are warnings, not errors', () => {
    beforeEach(() => {
      vi.mocked(repo.appendChangeLog).mockRejectedValue(new Error('Changelog writer is down'));
    });

    it('POST /:collection returns 200 with warning when create audit fails', async () => {
      const res = await request(appAs(true)).post('/library/virtues').send({ Name: 'New' });
      expect(res.status).toBe(200);
      expect(res.body.object.Name).toBe('New');
      expect(res.body.warning).toBe('Audit log entry could not be written');
      expect(repo.saveLibrary).toHaveBeenCalled();
      expect(repo.appendChangeLog).toHaveBeenCalled();
    });

    it('PUT /:collection/:id returns 200 with warning when update audit fails', async () => {
      const res = await request(appAs(true)).put('/library/virtues/v-might').send({ Tagline: 'Force' });
      expect(res.status).toBe(200);
      expect(res.body.object.Tagline).toBe('Force');
      expect(res.body.warning).toBe('Audit log entry could not be written');
      expect(repo.saveLibrary).toHaveBeenCalled();
      expect(repo.appendChangeLog).toHaveBeenCalled();
    });

    it('DELETE /:collection/:id returns 200 with warning when delete audit fails', async () => {
      const res = await request(appAs(true)).delete('/library/virtues/v-might');
      expect(res.status).toBe(200);
